"""Client-side validation for requests sent to the weather backend."""


def validate_payload(payload):
    """Return all request errors without consulting the backend.

    Keep this policy local: the backend's error response is deliberately not
    part of the client contract.
    """
    if not isinstance(payload, dict):
        return [{"field": "request", "message": "request must be an object"}]

    errors = []
    city = payload.get("city")
    if not isinstance(city, str) or not city.strip():
        errors.append({"field": "city", "message": "city required"})

    days = payload.get("days")
    if days is not None:
        if isinstance(days, bool) or not isinstance(days, int):
            errors.append({"field": "days", "message": "days must be an integer"})
        elif not 1 <= days <= 14:
            errors.append({"field": "days", "message": "days out of range"})

    units = payload.get("units")
    if units is not None and units not in {"metric", "imperial"}:
        errors.append({"field": "units", "message": "units must be metric or imperial"})

    return errors

